examples:
#include <Arduino.h>
#include "toki.h"

#define TACT GPIOA_NUM_15

void setup() {
  Serial.begin(115200);
  pinMode(TACT, INPUT_PULLUP);
}

void loop() {
  int switchState = digitalRead(TACT);

  if (switchState == HIGH) {
    Serial.println("Switch pressed");
  } else {
    Serial.println("Switch released");
  }

  delay(200);
}

