sections.description:
Define the output pin before starting the program:

pinMode(GPIOA_NUM_15, OUTPUT);

GPIOA_NUM_15: The GPIO pin used to generate the PWM signal.

void softPWM(uint8_t dutyPercent, uint16_t total_time_ms) {
  int loop_num = total_time_ms / 10;

  for (int i = 0; i < loop_num; i++) {
    digitalWrite(GPIOA_NUM_15, HIGH);
    delay(dutyPercent / 10);

    digitalWrite(GPIOA_NUM_15, LOW);
    delay((100 - dutyPercent) / 10);
  }
}

