sections.description:
Set pin as OUTPUT to send trigger pulse, then switch to INPUT to read echo:

pinMode(pin, OUTPUT);
digitalWrite(pin, LOW);
delayMicroseconds(2);
digitalWrite(pin, HIGH);
delayMicroseconds(10);
digitalWrite(pin, LOW);

pinMode(pin, INPUT);
duration = measurePulse(pin, HIGH, timeout);

distance = duration * 0.0343 / 2;

examples:
#include <Arduino.h>
#include "toki.h"

#define ULTRASONIC_PIN GPIOA_NUM_14

unsigned long measurePulse(gpio_num_t pin, uint8_t state, unsigned long timeout) {
  unsigned long start = micros();
  while (digitalRead(pin) != state) {
    if (micros() - start >= timeout) return 0;
  }
  unsigned long pulseStart = micros();
  while (digitalRead(pin) == state) {
    if (micros() - start >= timeout) return 0;
  }
  return micros() - pulseStart;
}

void setup() {
  Serial.begin(9600);
}

void loop() {
  pinMode(ULTRASONIC_PIN, OUTPUT);
  digitalWrite(ULTRASONIC_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(ULTRASONIC_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(ULTRASONIC_PIN, LOW);

  pinMode(ULTRASONIC_PIN, INPUT);
  unsigned long duration = measurePulse(ULTRASONIC_PIN, HIGH, 30000);

  float distance = duration * 0.0343f / 2.0f;
  Serial.print("Distance: ");
  Serial.print(distance, 1);
  Serial.println(" cm");

  delay(500);
}

