pinMode(MotorPinPWM, OUTPUT);
pinMode(MotorPinDir, OUTPUT);

digitalWrite(MotorPinDir, HIGH); // Direction
softPWM(dutyPercent, time);

digitalWrite(MotorPinDir, LOW); // Reverse Direction
softPWM(dutyPercent, time);

examples:
#include <Arduino.h>
#include "toki.h"

#define MotorPinPWM GPIOA_NUM_12
#define MotorPinDir GPIOA_NUM_13

void setup() {
  pinMode(MotorPinPWM, OUTPUT);
  pinMode(MotorPinDir, OUTPUT);
}

void softPWM(uint8_t dutyPercent, uint16_t total_time_ms) {
  int loop_num = total_time_ms / 10;
  for (int i = 0; i < loop_num; i++) {
    digitalWrite(MotorPinPWM, HIGH);
    delay(dutyPercent / 10);
    digitalWrite(MotorPinPWM, LOW);
    delay((100 - dutyPercent) / 10);
  }
}

void loop() {
  digitalWrite(MotorPinDir, HIGH);
  softPWM(30, 2000);

  digitalWrite(MotorPinDir, LOW);
  softPWM(30, 2000);
}
